def gen(rng):
    def fmt(js):
        return str(len(js)) + '\n' + '\n'.join(f'{s} {e} {p}' for s, e, p in js)
    tests = [fmt([(1, 2, 5)]), fmt([(1, 5, 3), (5, 10, 4)]), fmt([(1, 10, 4), (2, 9, 7), (3, 8, 6)]),
             fmt([(1, 10**9, 10000), (1, 5 * 10**8, 6000), (5 * 10**8, 10**9, 6000)]),
             fmt([(3, 7, 2), (3, 7, 2), (3, 7, 2)])]
    for n in (2, 3, 4, 6, 8, 10, 12):
        for _ in range(2):
            js = []
            for _ in range(n):
                s = rng.randint(1, 14)
                js.append((s, s + rng.randint(1, 8), rng.randint(1, 20)))
            tests.append(fmt(js))
    def big(n, mode):
        js = []
        for i in range(n):
            if mode == 0:
                s = rng.randint(1, 10**9 - 1)
                e = rng.randint(s + 1, min(10**9, s + rng.randint(1, 10**8)))
            elif mode == 1:
                s = rng.randint(1, 10**6)
                e = rng.randint(s + 1, 10**9)
            else:
                s = i * 40000 + rng.randint(1, 100)
                e = s + rng.randint(1, 120000)
            js.append((s, e, rng.randint(1, 10000)))
        return js
    tests.append(fmt(big(20000, 0)))
    tests.append(fmt(big(20000, 1)))
    tests.append(fmt(big(20000, 2)))
    tests.append(fmt(big(3000, 0)))
    return tests
